<template><Teleport to="body"><div v-if="open" class="backdrop" @click.self="open=false"><section role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="close" aria-label="Close" @click="open=false">×</button><img src="/icon_1-01.png" alt=""><span class="eyebrow">Join Blugbug</span><h2 id="auth-title">Keep the conversation going.</h2><p>Create an account or sign in to use this part of Blugbug. You can close this window and continue browsing as a guest.</p><router-link class="primary" :to="loginTarget">Sign in</router-link><router-link class="secondary" :to="signupTarget">Create account</router-link><button class="guest" @click="open=false">Continue as guest</button></section></div></Teleport></template>
<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRoute}from'vue-router';const route=useRoute(),open=ref(false);const redirect=computed(()=>encodeURIComponent(route.fullPath));const loginTarget=computed(()=>`/login?redirect=${redirect.value}`),signupTarget=computed(()=>`/signup?redirect=${redirect.value}`);const show=()=>open.value=true;onMounted(()=>window.addEventListener('blugbug:auth-required',show));onBeforeUnmount(()=>window.removeEventListener('blugbug:auth-required',show));</script>
<style scoped>.backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:20px;background:rgba(24,20,16,.62)}section{position:relative;width:min(410px,100%);display:grid;gap:11px;padding:34px;border:1px solid var(--line);border-radius:24px;background:var(--panel);box-shadow:0 26px 80px #0005}section>img{width:54px;height:54px;border-radius:50%}.close{position:absolute;top:14px;right:16px;border:0;background:none;color:var(--text);font-size:1.7rem}h2{margin:3px 0;font:700 2rem/1.05 Georgia,serif;color:var(--text)}p{margin:0 0 8px;color:var(--muted);line-height:1.55}.primary,.secondary,.guest{padding:13px;border-radius:12px;text-align:center;text-decoration:none;font-weight:900}.primary{background:var(--orange);color:#fff}.secondary{border:1px solid var(--orange);color:var(--orange)}.guest{border:0;background:none;color:var(--muted)} </style>
